using Astrea.BattleActions;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionToPlayerOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionToPlayer Omen Logic")]
public class BattleActionToPlayerOmenLogic : OmenLogic
{
	[Header("Player Game Object Reference")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private DirectPurifyCorruptEnum directPurifyCorruptEnum;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectPurify)
		{
			playerGameObjectReference.value.GetComponent<CorruptionStats>().Purify(actionValue, source);
		}
		else if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectCorrupt)
		{
			Debug.Log(corruptionPurifyModifierEnum);
			playerGameObjectReference.value.GetComponent<CorruptionStats>().Corrupt(actionValue, source, corruptionPurifyModifierEnum);
		}
		else
		{
			battleAction.CastTargetAmount(playerGameObjectReference.value, actionValue, source);
		}
	}
}
